package com.android.tools.lint.checks;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.JavaContext;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.SourceCodeScanner;
import com.intellij.psi.PsiClass;
import com.intellij.psi.PsiField;
import com.intellij.psi.PsiModifier;
import com.intellij.psi.PsiType;
import com.intellij.psi.util.InheritanceUtil;
import com.intellij.psi.util.PsiTypesUtil;
import java.util.Collections;
import java.util.List;
import org.jetbrains.uast.UClass;
import org.jetbrains.uast.UElement;
import org.jetbrains.uast.UField;
import org.jetbrains.uast.UAnnotation;
import org.jetbrains.uast.UastUtils;

public class ParcelDetector extends Detector implements SourceCodeScanner {
    private static final String CLASS_PARCELABLE = "android.os.Parcelable";
    private static final String CLASS_CREATOR = "android.os.Parcelable.Creator";
    private static final String FIELD_CREATOR = "CREATOR";
    private static final String PARCELIZE_ANNOTATION = "kotlinx.parcelize.Parcelize";
    private static final String LEGACY_PARCELIZE_ANNOTATION = "kotlinx.android.parcel.Parcelize";
    private static final String JVM_FIELD_ANNOTATION = "kotlin.jvm.JvmField";
    private static final String COMPANION_NAME = "Companion";

    public static final Issue ISSUE = Issue.create(
            "ParcelCreator",
            "Missing Parcelable `CREATOR` field",
            "According to the `Parcelable` interface documentation, classes implementing the "
                    + "`Parcelable` interface must also have a static field called `CREATOR`, "
                    + "which is an object implementing the `Parcelable.Creator` interface.",
            Category.CORRECTNESS,
            6,
            Severity.ERROR,
            new Implementation(ParcelDetector.class, Scope.JAVA_FILE_SCOPE)
    );

    @Nullable
    @Override
    public List<String> applicableSuperClasses() {
        return Collections.singletonList(CLASS_PARCELABLE);
    }

    @Override
    public void visitClass(@NonNull JavaContext context, @NonNull UClass declaration) {
        // skip interfaces etc.
        if (declaration.isInterface() || declaration.isAnnotationType() || declaration.isEnum()) {
            return;
        }
        PsiClass psi = declaration.getJavaPsi(); // or declaration
        if (psi != null && psi.hasModifierProperty(PsiModifier.ABSTRACT)) {
            return;
        }
        if (isParcelize(declaration)) {
            return;
        }

        // check direct static CREATOR
        PsiField directCreator = findDirectCreator(psi);
        if (directCreator != null) {
            return;
        }

        // check companion object CREATOR
        PsiClass companion = psi != null ? psi.findInnerClassByName(COMPANION_NAME, false) : null;
        if (companion != null) {
            PsiField companionCreator = findCreatorField(companion);
            if (companionCreator != null) {
                if (!hasJvmFieldAnnotation(companionCreator)) {
                    context.report(ISSUE, companionCreator, context.getNameLocation(companionCreator),
                            "Field should be annotated with @JvmField");
                }
                return;
            }
        }

        context.report(ISSUE, declaration, context.getNameLocation(declaration),
                "This class implements Parcelable but is missing the required `CREATOR` field");
    }
}
