private static PsiField findCreatorField(PsiClass cls) {
    for (PsiField field : cls.getFields()) {
        if (FIELD_CREATOR.equals(field.getName()) && isCreatorType(field.getType())) {
            return field;
        }
    }
    return null;
}

private static boolean isValidCreatorField(PsiField field) {
    return FIELD_CREATOR.equals(field.getName())
        && field.hasModifierProperty(PsiModifier.PUBLIC)
        && field.hasModifierProperty(PsiModifier.STATIC)
        && field.hasModifierProperty(PsiModifier.FINAL)
        && isCreatorType(field.getType());
}

private static boolean isCreatorType(PsiType type) {
    PsiClass cls = PsiTypesUtil.getPsiClass(type);
    if (cls != null && InheritanceUtil.isInheritor(cls, CLASS_CREATOR)) return true;
    String text = type.getCanonicalText();
    return CLASS_CREATOR.equals(text) || text.startsWith(CLASS_CREATOR + "<");
}
```

